Bash(cd "C:/Users/etien/Desktop/CETé" && node -e "
const clients = require\('./src/data/mocks/fr/clients.json'\).clients;
const docs = require\('./src/data/mocks/fr/contract_documents.json'\).contractDocuments;
const evals = require\('./src/data/mocks/fr/evaluations.json'\).evaluations;

const clientIds = new Set\(clients.map\(c => c.id\)\);
const docIds = new Set\(docs.map\(d => d.id\)\);

// Check all doc.clientId references exist
const badDocs = docs.filter\(d => !clientIds.has\(d.clientId\)\);
if \(badDocs.length\) console.error\('Bad doc clientId refs:', badDocs.map\(d => d.id\)\);

// Check all eval.clientId references exist
const badEvals = evals.filter\(e => !clientIds.has\(e.clientId\)\);
if \(badEvals.length\) console.error\('Bad eval clientId refs:', badEvals.map\(e => e.id\)\);

// Check all eval.reportDocumentId references exist
const badReportRefs = evals.filter\(e => e.reportDocumentId && !docIds.has\(e.reportDocumentId\)\);
if \(badReportRefs.length\) console.error\('Bad reportDocumentId refs:', badReportRefs.map\(e => e.id\)\);

// Check auditorId refs match founder IDs \(1,2,3,4\)
const founderIds = new Set\(['1','2','3','4']\);
const badAuditors = evals.filter\(e => !founderIds.has\(e.auditorId\)\);
if \(badAuditors.length\) console.error\('Bad auditorId refs:', badAuditors.map\(e => e.id\)\);

// Summary
console.log\('Clients:', clients.length\);
console.log\('Documents:', docs.length\);
console.log\('Evaluations:', evals.length\);
console.log\('Docs per client:', Object.fromEntries\(
  clients.map\(c => [c.companyName, docs.filter\(d => d.clientId === c.id\).length]\)
\)\);
console.log\('Evals per client:', Object.fromEntries\(
  clients.map\(c => [c.companyName, evals.filter\(e => e.clientId === c.id\).length]\)
\)\);
console.log\('All cross-references OK'\);
")
